import type { Metadata } from "next";
import { Suspense } from "react";
import { VariantBar, VersionSwitcher } from "@/components/version-switcher";
import { getProduct } from "@/lib/products";
import { getSnapshots, getVersions, versionOf } from "@/lib/snapshots";

// The page around a frozen version of a product (its route is generated by
// scripts/snapshot.mjs): the version itself, full screen, plus the switcher,
// and for a variant of a group, the variant bar too.
// Like the live product's page, it renders inside a Suspense boundary so the
// app can read the clock while it prerenders.
export function SnapshotPage({ slug, id, children }: { slug: string; id: string; children: React.ReactNode }) {
  return (
    <Suspense>
      {children}
      <Switcher slug={slug} id={id} />
    </Suspense>
  );
}

async function Switcher({ slug, id }: { slug: string; id: string }) {
  const { metadata } = await getProduct(slug);
  const versions = getVersions(slug);
  // a variant shows under its group in the version bar, and gets the variant bar for its siblings
  const version = versionOf(versions, id);
  const next = version && versions[versions.indexOf(version) + 1];
  return (
    <>
      <VersionSwitcher slug={slug} versions={versions} current={version?.id ?? id} placement={metadata.versionBar} />
      {version?.variants && (
        <VariantBar
          slug={slug}
          variants={version.variants}
          current={id}
          next={next && { id: next.id, name: next.name }}
          placement={metadata.versionBar}
        />
      )}
    </>
  );
}

export function snapshotMetadata(slug: string, id: string): Metadata {
  const snapshot = getSnapshots(slug).find((s) => s.id === id);
  return { title: snapshot?.name ?? id };
}
